args.value:
() => {
  const panel = document.querySelector('kat-panel[data-testid="kat-panel-B2BInsightsActionPanel"]');
  const radios = Array.from(panel.querySelectorAll('kat-radio-button, kat-radio-group'));
  return radios.map(r => ({
    tag: r.tagName,
    value: r.value,
    label: r.label,
    checked: r.checked,
    outerHTML: r.outerHTML.slice(0, 300)
  }));
}
